import Link from "next/link";
import { prisma } from "@/core/server/prisma";
import { CmsLifecycleControls } from "@/modules/cms/components/CmsLifecycleControls";
import { CmsEmptyState, CmsPageShell } from "@/modules/cms/components/CmsPageShell";

export default async function CmsModulesPage() {
  const modules = await prisma.courseModule.findMany({ take: 200, orderBy: { updatedAt: "desc" }, include: { course: { select: { id: true, title: true, level: { select: { code: true } } } }, _count: { select: { lessons: true } } } });
  return <CmsPageShell eyebrow="Learning content" title="Modules" description="Modules keep their own lifecycle, order, prerequisites and completion rule. Open a module to edit its unlock conditions or preview its learner outline.">{modules.length === 0 ? <CmsEmptyState description="Create a course and its first module to start building lessons." /> : <div className="space-y-3">{modules.map((module) => <article key={module.id} className="flex flex-wrap items-start justify-between gap-4 rounded-2xl border border-slate-200 bg-white p-5"><div><p className="text-xs font-semibold text-blue-700">{module.course.level.code} · <Link href={`/cms/courses/${module.course.id}`} className="hover:underline">{module.course.title}</Link></p><h2 className="mt-1 text-lg font-bold text-slate-950">{module.order}. {module.title}</h2><p className="mt-1 text-sm text-slate-600">{module.description ?? "No description."} · {module._count.lessons} lessons</p><p className="mt-2 text-xs font-semibold text-slate-500">{module.isRequired ? "Required" : "Optional"} · {module.requiresSequentialCompletion ? "Previous module required" : "No sequential lock"}{module.unlockAfterModuleId ? ` · Explicit prerequisite at ${module.requiredCompletionPercent}%` : ""}</p></div><div className="flex flex-wrap gap-2"><Link href={`/cms/modules/${module.id}`} className="rounded border border-slate-300 px-2 py-1 text-xs font-semibold hover:bg-slate-50">Edit</Link><Link href={`/cms/preview/modules/${module.id}`} className="rounded border border-slate-300 px-2 py-1 text-xs font-semibold hover:bg-slate-50">Preview</Link><CmsLifecycleControls entityType="COURSE_MODULE" entityId={module.id} status={module.contentStatus} compact /></div></article>)}</div>}</CmsPageShell>;
}
